}

fn checkpoint_for(policy: &Policy, loaded: &Loaded) -> Result<u64, String> {
    match policy.checkpoint_mode.as_str() {
        "MAX_SEEN" => Ok(loaded.max_sequence),
        "PIN_PENDING" => {
            let pin = loaded.pending.iter().map(|item| item.target_sequence.saturating_sub(1)).min();
            Ok(pin.map(|value| value.min(loaded.max_sequence)).unwrap_or(loaded.max_sequence))
        }
        "READ_ONLY" => Ok(loaded.checkpoint),
        _ => Err("unknown checkpoint mode".to_string()),
    }
}

fn recover_pending_resolutions(state_dir: &Path, loaded: &mut Loaded) -> Result<(), String> {
    let mut lines = Vec::new();
    let mut resolutions = Vec::new();
    let mut resolved_targets = loaded.reversed_targets.clone();

    for pending in &loaded.pending {
        if resolved_targets.contains(&pending.target_id) {
            continue;
        }
        let Some((charge_sequence, amount_cents)) = loaded.charges.get(&pending.target_id).copied() else {
            continue;
        };
        if charge_sequence != pending.target_sequence {
            continue;
        }

        lines.push(format!("T|{}|{}|{}", pending.reversal_id,
                           pending.target_id, amount_cents));
        resolutions.push((pending.reversal_id.clone(), pending.target_id.clone(), amount_cents));
        resolved_targets.insert(pending.target_id.clone());
    }

    if lines.is_empty() {
        return Ok(());
    }

    append_lines(&state_dir.join("ledger.log"), &lines)?;
    loaded.journal_entries += lines.len();
    for (reversal_id, target_id, amount_cents) in resolutions {
        loaded.reversed_targets.insert(target_id);
        loaded.pending.retain(|pending| pending.reversal_id != reversal_id);
        loaded.balance_cents -= amount_cents as i64;
    }
    Ok(())
}

fn write_derived_state(state_dir: &Path, loaded: &Loaded) -> Result<(), String> {
    atomic_write(&state_dir.join("checkpoint.state"),
                 format!("{}\n", loaded.checkpoint).as_bytes())?;
    atomic_write(&state_dir.join("balance.state"),
                 format!("{}\n", loaded.balance_cents).as_bytes())
}

fn append_lines(path: &Path, lines: &[String]) -> Result<(), String> {
    let mut file = OpenOptions::new().create(true).append(true).open(path)
        .map_err(|error| error.to_string())?;
    for line in lines {
        file.write_all(line.as_bytes()).map_err(|error| error.to_string())?;
        file.write_all(b"\n").map_err(|error| error.to_string())?;
    }
    file.sync_all().map_err(|error| error.to_string())
}

fn atomic_write(path: &Path, bytes: &[u8]) -> Result<(), String> {
    let name = path.file_name().and_then(|value| value.to_str())
        .ok_or_else(|| "state path must have a UTF-8 file name".to_string())?;
    let temporary = path.with_file_name(format!(".{}.{}.part", name, std::process::id()));
    let result = (|| -> Result<(), String> {
        let mut file = OpenOptions::new().write(true).create_new(true).open(&temporary)
            .map_err(|error| error.to_string())?;
        file.write_all(bytes).map_err(|error| error.to_string())?;
        file.sync_all().map_err(|error| error.to_string())?;
        fs::rename(&temporary, path).map_err(|error| error.to_string())
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

